  &lt;script id=&#34;hbeData&#34; type=&#34;hbeData&#34;&gt;
    
  &lt;/script&gt;
  &lt;div class=&#34;hbe hbe-content&#34;&gt;
    &lt;form id=&#34;hbeForm&#34; class=&#34;hbe hbe-form&#34; onsubmit=&#34;return false&#34;&gt;
